// Decode argv bytes exactly like CPython: UTF-8 strict + surrogateescape.
// Returns array of code points (ints). Invalid byte b -> 0xDC00+b.
function decodeSurrogateescape(buf) {
  const cps = []; let i = 0;
  const cont = (k) => i + k < buf.length && (buf[i + k] & 0xC0) === 0x80;
  while (i < buf.length) {
    const b = buf[i];
    if (b < 0x80) { cps.push(b); i += 1; continue; }
    let len = 0, cp = 0, lo = 0;
    if (b >= 0xC2 && b <= 0xDF) { len = 2; cp = b & 0x1F; lo = 0x80; }
    else if (b >= 0xE0 && b <= 0xEF) { len = 3; cp = b & 0x0F; lo = 0x800; }
    else if (b >= 0xF0 && b <= 0xF4) { len = 4; cp = b & 0x07; lo = 0x10000; }
    if (len === 0) { cps.push(0xDC00 + b); i += 1; continue; }
    let ok = true;
    for (let k = 1; k < len; k++) if (!cont(k)) { ok = false; break; }
    if (ok) { for (let k = 1; k < len; k++) cp = (cp << 6) | (buf[i + k] & 0x3F); }
    // reject overlong, surrogates, >U+10FFFF
    if (!ok || cp < lo || cp > 0x10FFFF || (cp >= 0xD800 && cp <= 0xDFFF)) {
      cps.push(0xDC00 + b); i += 1; continue;
    }
    cps.push(cp); i += len;
  }
  return cps;
}
function encodeSurrogateescape(cps) {
  const out = [];
  for (const cp of cps) {
    if (cp >= 0xDC80 && cp <= 0xDCFF) { out.push(cp - 0xDC00); continue; }
    if (cp < 0x80) out.push(cp);
    else if (cp < 0x800) out.push(0xC0 | (cp >> 6), 0x80 | (cp & 63));
    else if (cp < 0x10000) out.push(0xE0 | (cp >> 12), 0x80 | ((cp >> 6) & 63), 0x80 | (cp & 63));
    else out.push(0xF0 | (cp >> 18), 0x80 | ((cp >> 12) & 63), 0x80 | ((cp >> 6) & 63), 0x80 | (cp & 63));
  }
  return Buffer.from(out);
}
// printable test: use JS RegExp Unicode property escapes (Node 18 supports them)
const NONPRINT = /^[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]$/u;
function isPrintableCp(cp) {
  if (cp === 0x20) return true;
  const s = String.fromCodePoint(cp);
  return !NONPRINT.test(s);
}
function reprBody(cps) {
  let out = '';
  for (const cp of cps) {
    if (cp === 0x27) { out += "\\'"; continue; }          // untested here
    if (cp === 0x5C) { out += '\\\\'; continue; }
    if (isPrintableCp(cp)) { out += String.fromCodePoint(cp); continue; }
    if (cp === 0x0A) { out += '\\n'; continue; }
    if (cp === 0x0D) { out += '\\r'; continue; }
    if (cp === 0x09) { out += '\\t'; continue; }
    if (cp < 0x100) out += '\\x' + cp.toString(16).padStart(2, '0');
    else if (cp < 0x10000) out += '\\u' + cp.toString(16).padStart(4, '0');
    else out += '\\U' + cp.toString(16).padStart(8, '0');
  }
  return out;
}
const hex = process.argv[2];
const buf = Buffer.from(hex, 'hex');
const cps = decodeSurrogateescape(buf);
process.stdout.write("'" + reprBody(cps) + "'\n");
process.stdout.write(encodeSurrogateescape(cps));
process.stdout.write('\n');
EOF
